from datetime import datetime, date
import holidays

def total_business_days(date_ranges, country='US'):
    """
    Calculate the total number of business days across multiple date ranges
    for a given country, excluding weekends and public holidays.

    Parameters
    ----------
    date_ranges : list of tuple
        Each tuple contains (start_date, end_date), inclusive of both endpoints.
        Dates may be datetime.date, datetime.datetime, pandas.Timestamp, or
        strings in 'YYYY-MM-DD' format.
    country : str
        ISO country code used to look up public holidays (default 'US').

    Returns
    -------
    int
        Total count of business days across all provided date ranges.
    """
    def _to_date(d):
        if isinstance(d, datetime):
            return d.date()
        if isinstance(d, date):
            return d
        # Covers strings and pandas Timestamps via datetime parsing
        return pd.Timestamp(d).date()

    holiday_cache = {}

    def _get_holidays(year):
        if year not in holiday_cache:
            try:
                holiday_cache[year] = getattr(holidays, country)(years=year)
            except AttributeError:
                raise ValueError(f"Unsupported country code: {country!r}")
        return holiday_cache[year]

    def _is_business_day(d):
        return d.weekday() < 5 and d not in _get_holidays(d.year)

    total = 0
    for start, end in date_ranges:
        start = _to_date(start)
        end = _to_date(end)
        if start > end:
            continue  # ignore invalid/reversed ranges
        # Efficient iteration with pandas business-day calendar, then filter holidays
        total += sum(1 for d in pd.date_range(start, end, freq='D').date
                     if _is_business_day(d))
    return total


